{
  "query": "Lang Owens 2019 \"A variational approach to data assimilation in the solar wind\" Space Weather BRaVDA STEREO in situ improvement RMSE",
  "mode": "standard"
}

{
  "query": "Lang Witherington Turner Owens Riley 2021 \"Improving solar wind forecasting using data assimilation\" Space Weather e2020SW002698 STEREO RMSE reduction",
  "mode": "standard"
}

{
  "url": "https://arxiv.org/abs/2012.06362v3",
  "prompt": "Quote the abstract verbatim and key points: what is assimilated (speed only?), which spacecraft (STEREO-A/B, ACE), model (HUXt, MAS at 30 Rs), period, RMSE reduction, journal ref."
}

{
  "url": "https://essopenarchive.org/users/555501/articles/628410-solar-wind-data-assimilation-in-an-operational-context-use-of-near-real-time-data-and-the-forecast-value-of-an-l5-monitor",
  "prompt": "Give title, authors, journal/year, abstract: use of near-real-time STEREO-A beacon data in BRaVDA, results, RMSE improvements."
}

{
  "query": "Turner Lang Owens 2023 Space Weather \"Solar wind data assimilation in an operational context\" near-real-time STEREO-A beacon BRaVDA L5",
  "mode": "standard"
}

{
  "url": "https://arxiv.org/abs/1806.07306",
  "prompt": "Quote the abstract: what is assimilated (speed), model (Riley-Lionello? 'simple solar wind propagation model'), observation sources (STEREO-A, STEREO-B, ACE), period, improvement. Journal ref."
}

{
  "query": "PUNCH mission science data release 2025 Level 3 public data SDAC punch.space.swri.edu data products",
  "mode": "extended"
}

{
  "query": "LOFAR 2.0 upgrade downtime 2025 2026 IPS interplanetary scintillation space weather observations stopped",
  "mode": "extended"
}

{
  "query": "GOES-19 CCOR-1 coronagraph operational status 2025 SWPC declared operational imagery available",
  "mode": "extended"
}

{
  "url": "https://www.spaceweather.gov/products/coronagraph",
  "prompt": "Quote verbatim statements about CCOR-1 operational status/date, cadence, data access URLs (services.swpc.noaa.gov, NCEI), and any note about outages."
}

{
  "url": "https://cdaw.gsfc.nasa.gov/CME_list/",
  "prompt": "What is the latest month/year covered by the SOHO LASCO CME catalog listed here? Is November 2025 and December 2025 listed? Quote any notes about preliminary status."
}

{
  "url": "https://www.sidc.be/cactus/",
  "prompt": "What data sources does CACTus cover (LASCO C2/C3, STEREO-A COR2, CCOR)? Is there a catalog for November/December 2025? List URLs for the LASCO and SECCHI/COR2 catalogs, real-time quicklook, and the latest month available. Any notes on outages."
}

{
  "url": "https://www.sidc.be/cactus/catalog.php",
  "prompt": "What years/months are available in the LASCO CACTus catalog (qkl and lz)? Is 2025 Nov/Dec available? Give the exact link URL patterns for monthly catalogs."
}

{
  "url": "https://secchi.nrl.navy.mil/cactus/",
  "prompt": "What period does this STEREO COR2 CACTus list cover? Is November/December 2025 available for COR2-A? Give the URL pattern for monthly lists."
}

{
  "url": "https://www.ukssdc.ac.uk/solar/stereo/data.html",
  "prompt": "Describe the STEREO HI data available here: beacon vs science (L1/L2), latest dates available, URL paths for HI-1/HI-2 Ahead science and beacon data."
}

{
  "url": "https://stereo-ssc.nascom.nasa.gov/data/",
  "prompt": "Describe the directory structure: beacon vs ins_data (science) for SECCHI HI; latest dates; URLs."
}
